void readInt(int &x) {
    char c;
    x = 0;
    bool neg = false;
    while (!isdigit(c = getchar())) {
        if (c == '-') neg = true;
    }
    do {
        x = x * 10 + (c - '0');
    } while (isdigit(c = getchar()));
    if (neg) x = -x;
}

void readLL(long long &x) {
    char c;
    x = 0;
    bool neg = false;
    while (!isdigit(c = getchar())) {
        if (c == '-') neg = true;
    }
    do {
        x = x * 10 + (c - '0');
    } while (isdigit(c = getchar()));
    if (neg) x = -x;
}

long long n, k, MOD;
int fact[262155];
int invFact[262155];

int modExp(int base, long long exp) {
    int res = 1;
    while (exp) {
        if (exp & 1) {
            res = (long long)res * base % MOD;
        }
        base = (long long)base * base % MOD;
        exp >>= 1;
    }
    return res;
}

int memo[262155][31];
bool marked[262155][31];
int log2arr[262155];

int get2adic(int x) {
    int cnt = 0;
    while ((x & 1) == 0 && x) {
        ++cnt;
        x >>= 1;
    }
    return cnt;
}

int twoadicSum[262155];

int binomial(int N, int M) {
    return (long long)fact[N] * invFact[M] % MOD * invFact[N - M] % MOD;
}

int recursiveDP(int N, int K) {
    if (N == 0) return 1;
    if (K == 0) return 0;
    if (memo[N][K] != -1) return memo[N][K];

    int step = 1 << log2arr[N];
    int sum = 0;
    for (int i = N; i >= step; i -= 2) {
        sum = (sum + (long long)binomial(N, i) * recursiveDP(N - i, K - 1) % MOD * K) % MOD;
    }
    return memo[N][K] = sum;
}

vector<pair<int, int>> traversal;

int iterativeDP(int N, int K) {
    queue<pair<int, int>> q;
    q.push({N, K});

    while (!q.empty()) {
        int curN = q.front().first;
        int curK = q.front().second;
        q.pop();
        traversal.push_back({curN, curK});

        if (curN == 0 || curK == 0) continue;

        int step = 1 << log2arr[curN];
        for (int i = curN; i >= step; i -= 2) {
            if (twoadicSum[i] + twoadicSum[curN - i] == twoadicSum[curN] && !marked[curN - i][curK - 1]) {
                marked[curN - i][curK - 1] = true;
                q.push({curN - i, curK - 1});
            }
        }
    }

    for (int i = traversal.size() - 1; i >= 0; --i) {
        int curN = traversal[i].first;
        int curK = traversal[i].second;

        if (curN == 0) {
            memo[curN][curK] = 1;
            continue;
        }
        if (curK == 0) {
            memo[curN][curK] = 0;
            continue;
        }

        int step = 1 << log2arr[curN];
        for (int i = curN; i >= step; i -= 2) {
            if (twoadicSum[i] + twoadicSum[curN - i] == twoadicSum[curN]) {
                memo[curN][curK] = (memo[curN][curK] + (long long)binomial(curN, i) * memo[curN - i][curK - 1] % MOD * curK) % MOD;
            }
        }
    }

    return memo[N][K];
}

