        fact[i] = (long long)fact[i - 1] * i % MOD;
        log2arr[i] = log2arr[i >> 1] + 1;
        twoadicSum[i] = twoadicSum[i - 1] + get2adic(i);
    }

    invFact[262150] = modExp(fact[262150], MOD - 2);
    for (int i = 262149; i >= 1; --i) {
        invFact[i] = (long long)invFact[i + 1] * (i + 1) % MOD;
    }

    invFact[0] = invFact[1];

    if (n & 1) {
        cout << modExp(k, n) << '\n';
    } else {
        int total = modExp(k, n);
        int result = iterativeDP(n, k);
        cout << ((total - result) % MOD + MOD) % MOD;
    }
}
